import sympy as sp; x = sp.Symbol('x'); f = 2*x**2 + 6*x + 6; lhs = (x+3)*f; rhs = sp.integrate(4*f.subs(x, sp.Symbol('t')) - 2*sp.Symbol('t')**2, (sp.Symbol('t'), -3, x)); lhs_expanded = sp.expand(lhs); rhs_expanded = sp.expand(rhs); check1 = sp.simplify(lhs_expanded - rhs_expanded) == 0; f2 = f.subs(x, 2); result = 'VERIFY_PASS' if check1 and f2 == 26 else 'VERIFY_FAIL'; print(result)